//! Bounded ten-episode storyboard planning for the numbered screenplay generated by long-form expansion.

use std::collections::HashSet;

use serde_json::{json, Value};

use crate::{
    error::{AppError, AppResult},
    planner, skills,
    value::NOT_GENERATED,
};

use super::{expansion::support, DurableWorker};

const DECOMPOSITION_START_PROGRESS: i64 = 65;
const DECOMPOSITION_END_PROGRESS: i64 = 75;
const STREAM_PROGRESS_REPORT_CHARS: usize = 1_000;

impl DurableWorker {
    /// Plan every persisted long-form episode in ten-episode model batches instead of collapsing it into a short fallback.
    pub(super) fn long_form_plan(
        &self,
        task_id: &str,
        project: &Value,
        screenplay: &str,
    ) -> AppResult<Value> {
        let target = support::target_episode_count(project)?;
        let sections = support::episode_sections(screenplay);
        if sections.len() < target as usize {
            return Err(AppError::BadRequest(format!(
                "扩写剧本不足{target}集，不能进入长剧分镜"
            )));
        }
        let model = project["language_model"].as_str();
        let enable_web = project["enable_web_search"].as_bool().unwrap_or(false);
        let mut episodes = Vec::new();
        let mut assets: Vec<Value> = Vec::new();
        let batches = &sections[..target as usize];
        let batch_count = (batches.len() + 9) / 10;
        let decomposer = skills::drama_skill(
            "script_decomposer",
            json!({
                "shot_script_max_chars": project["shot_script_max_chars"].as_i64().unwrap_or(400),
            }),
        )?;
        let decomposer_instruction = decomposer["instruction"].as_str().unwrap_or_default();
        for (batch_index, batch) in batches.chunks(10).enumerate() {
            let known_character_names = assets
                .iter()
                .filter(|asset| asset["type"] == "character")
                .filter_map(|asset| asset["name"].as_str().map(str::to_owned))
                .collect::<Vec<_>>();
            let progress = batch_progress(batch_index, batch_count);
            let mut received_chars = 0;
            let mut next_report_at = STREAM_PROGRESS_REPORT_CHARS;
            let stage = batch_stage(batch, batch_index, batch_count, received_chars);
            self.repository
                .update_drama_task_progress(task_id, progress, &stage)?;
            let response = self
                .providers
                .complete_with_web_search_content_stream(
                    "language",
                    model,
                    &format!(
                        "{}\n\n你是短剧分镜总监。严格按照用户要求返回合法 JSON，不要 Markdown。\n\n拆解执行规范：\n{}",
                        skills::drama_agent_system()?,
                        decomposer_instruction,
                    ),
                    &batch_prompt(project, batch, &known_character_names),
                    enable_web,
                    |delta| {
                        received_chars += delta.chars().count();
                        if received_chars >= next_report_at {
                            self.repository.update_drama_task_progress(
                                task_id,
                                progress,
                                &batch_stage(batch, batch_index, batch_count, received_chars),
                            )?;
                            next_report_at = received_chars + STREAM_PROGRESS_REPORT_CHARS;
                        }
                        Ok(())
                    },
                )
                .map_err(|error| AppError::External(format!("{stage}生成失败：{error}")))?;
            let parsed = response
                .and_then(|res| planner::parse_json_object(&res))
                .unwrap_or_else(|| json!({}));
            for (index, section) in batch.iter().enumerate() {
                let raw = parsed["episodes"]
                    .as_array()
                    .and_then(|items| {
                        items
                            .iter()
                            .find(|item| episode_number(item) == Some(section.number))
                            .or_else(|| items.get(index))
                    })
                    .unwrap_or(&Value::Null);
                episodes.push(json!({"name":format!("第{}集：{}",section.number,section.title),"shots":long_shots(raw, section, project)}));
            }
            assets.extend(
                parsed["assets"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter_map(valid_asset),
            );
            if let Ok(Some(inventory)) = self.providers.complete(
                "language",
                model,
                &format!(
                    "{}\n\n你只负责素材盘点。严格输出合法 JSON，不要 Markdown。\n\n拆解执行规范：\n{}",
                    skills::drama_agent_system()?,
                    decomposer_instruction,
                ),
                &asset_inventory_prompt(project, batch),
            ) {
                let inventory = planner::parse_json_object(&inventory).unwrap_or_else(|| json!({}));
                assets.extend(
                    inventory["assets"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(valid_asset),
                );
            }
        }
        assets.extend(planner::extracted_assets(
            screenplay,
            project["theme"].as_str().unwrap_or("都市"),
        ));
        Ok(json!({"episodes":episodes,"assets":unique_assets(assets)}))
    }
}

/// Reserve the 65–75% range for verified completed batches of long-form decomposition.
fn batch_progress(batch_index: usize, batch_count: usize) -> i64 {
    let total = batch_count.max(1) as i64;
    let completed = (batch_index as i64).clamp(0, total);
    let range = DECOMPOSITION_END_PROGRESS - DECOMPOSITION_START_PROGRESS;
    DECOMPOSITION_START_PROGRESS + (range * completed + total / 2) / total
}

/// Describe the current durable batch and periodically report received model output without excessive SQLite writes.
fn batch_stage(
    batch: &[support::Episode],
    batch_index: usize,
    batch_count: usize,
    received_chars: usize,
) -> String {
    let start = batch.first().map(|item| item.number).unwrap_or_default();
    let end = batch.last().map(|item| item.number).unwrap_or_default();
    let stage = format!(
        "第{start}至{end}集分镜骨架（第{}/{batch_count}批）",
        batch_index + 1
    );
    if received_chars == 0 {
        stage
    } else {
        format!("{stage}，已接收{received_chars}字")
    }
}

fn batch_prompt(
    project: &Value,
    batch: &[support::Episode],
    known_character_names: &[String],
) -> String {
    let subtitles = project["shot_constraints"]["subtitles"]
        .as_bool()
        .unwrap_or(false);
    let music = project["shot_constraints"]["background_music"]
        .as_bool()
        .unwrap_or(false);
    let script = batch
        .iter()
        .map(|item| format!("【第{:03}集：{}】\n{}", item.number, item.title, item.body))
        .collect::<Vec<_>>()
        .join("\n\n");
    let known_characters = if known_character_names.is_empty() {
        "无（这是首批剧情）".to_owned()
    } else {
        known_character_names.join("、")
    };
    format!("你正在生成长剧的分镜骨架。请使用 web_search 仅在需要校验通用类型节奏时查询，不得复制任何搜索到的作品内容。只返回合法 JSON：顶层包含 episodes 与 assets；episode 有 name、shots；shot 有 title、original_text、prompt、duration、references；references 每项有 asset_type、asset_name，角色处于非基础形态时额外有 variant_name。asset 有 id、type、name、prompt，角色额外有 voice_id、variants；每个 variant 有 name、prompt、episode_numbers。\n必须且只能拆解第{:03}至第{:03}集，不得合并、遗漏或新增集数。每集生成2至4条按顺序衔接的分镜；每条分镜默认 duration 为 10 秒；original_text 不超过{}字，只能来自该集的局部事件，不能复制整集或整剧。references 必须逐镜列出实际出现的场景、角色、道具；若角色处于幼年、少年、成年、老年、伤病、变身、换装或其他外观明显不同的形态，必须填写该角色对应 variant_name，绝不可只引用角色本体。每个 prompt 必须含有‘场景：’、‘角色：’、‘风格：’、‘光线：’、‘位置：’以及至少两个‘【镜头’段落，并使用 @图1（场景）、@图2（角色形态）、@图3（道具）形式预留参考图，文本需分段换行。项目创建配置：目标剧集数={}集；风格={}；题材={}；画幅={}；分辨率={}；分镜元素约束={}。{}{}\n人物首次出场规则：人物第一次在全剧清晰出场时，必须在其首个 original_text 保留或补写“【人物首次出场：当前名字｜人物描述：身份或关系、年龄/形态、2～3项稳定外观、当下情绪或动作】”，并同步写入 prompt 的对应镜头。该镜头还必须写入“【人物姓名标识｜姓名：当前名字｜时长：1～2s｜位置：人物近旁且不遮挡脸部｜效果：快速淡入淡出】”。姓名用当前剧情名或 character 的当前 name；姓名标识不是字幕，即使关闭字幕也必须保留，且同一人物只在首次出场展示一次。此前批次已确认出场的角色：{known_characters}；这些角色不得重复标记为首次出场。\n素材提取是本批的独立交付物：先覆盖阅读本批每一集，再逐项列出全部实际出现且可复用的角色、场景、道具。所有有姓名或稳定称谓且参与动作、对白、冲突或剧情推进的人物必须输出 character；所有承载实际剧情且可复用的地点或空间必须输出 scene；所有被持有、使用、寻找、展示或推动剧情的关键物件必须输出 prop。数量必须由文本中的实体数决定，不得按每类 2 个、每批 2 个或任意固定数量截断；不要用“主要角色”“关键道具”等泛称代替具体实体。角色 base prompt 写身份锚点与基础形态；只要剧本明确同一角色有两个或以上可视觉区分的生命阶段、身体状态、身份/服装状态或变身状态，就必须在该角色 variants 完整输出每个非基础形态，不得把幼年与成年合并为一张图，也不得只保留后期成年形态。variant prompt 必须独立写清年龄/阶段、脸型体态、发型、服装配饰、伤痕或状态变化，并说明与角色身份锚点保持同一人。每个素材 prompt 是该素材专属描述，不能使用公共提示词或剧本摘要：第一行写‘叙述背景主题：{}’；角色写身份、年龄性别、至少三项可观察性格行为以及脸型、眉眼、发型、体型、服装和配饰等稳定外观；场景写剧情用途、空间结构、陈设状态、色调光线、氛围，并限制无人物无背景文字；道具写叙事用途、颜色、材质、尺寸/形制、纹理磨损、装饰及表面文字限制。每位角色必须从下列音色 ID 选择最匹配的一项：broken_whisper_resilient_female、cold_boss_male、cool_career_newcomer_male、soft_puppy_boyfriend_male、sickly_gloomy_yandere_male、ruthless_old_fox_male、arrogant_genius_male、cool_abstinent_detective_female、warm_older_brother_male、sweet_cold_yandere_male、cold_royal_sister_female、strong_female_lead、mature_warm_goddess_female、sweet_fox_tease_female。\n本批剧本：\n{script}", batch[0].number,batch.last().map(|item|item.number).unwrap_or_default(),project["shot_script_max_chars"].as_i64().unwrap_or(400),project["episode_count"],project["style"].as_str().unwrap_or("真人风格"),project["theme"].as_str().unwrap_or("都市"),project["ratio"].as_str().unwrap_or("9:16"),project["resolution"].as_str().unwrap_or("720p"),project["shot_constraints"],if subtitles { "按剧情需要标注字幕信息。" } else { "不得出现字幕、屏幕文字或水印。" },if music { "可按剧情需要标注背景音乐。" } else { "不得出现背景音乐描述。" },project["theme"].as_str().unwrap_or("都市"))
}

/// Ask for a compact, batch-scoped material catalog separately from verbose storyboard output.
fn asset_inventory_prompt(project: &Value, batch: &[support::Episode]) -> String {
    let script = batch
        .iter()
        .map(|item| format!("【第{:03}集：{}】\n{}", item.number, item.title, item.body))
        .collect::<Vec<_>>()
        .join("\n\n");
    format!(
        "只返回 JSON 对象 {{\"assets\":[...]}}，不要输出 episodes、shots、解释或 Markdown。请完整盘点下面第{:03}至第{:03}集实际出现的可复用素材：人物、发生剧情的空间、关键道具。不得设定每类 2 个或任何数量上限；不能遗漏有姓名或稳定称谓且参与剧情的人物、实际发生剧情的场景、被持有/使用/寻找/展示/推动剧情的物件。asset 字段为 type（character/scene/prop）、name、prompt，角色额外带 voice_id、variants；每个 variant 有 name、prompt、episode_numbers。只要剧本内同一角色存在幼年/少年/成年/老年、变身、伤病、明显换装或其他可视觉辨别形态，必须完整列入 variants，不能仅保留其中一个阶段；variant prompt 要明确此阶段的年龄、外貌、发型、体态、服饰与状态变化。每项 prompt 必须是该实体独立、可用于图片生成的描述，第一行写“叙述背景主题：{}”。\n\n本批剧本：\n{script}",
        batch[0].number,
        batch.last().map(|item| item.number).unwrap_or_default(),
        project["theme"].as_str().unwrap_or("都市"),
    )
}

fn long_shots(raw: &Value, section: &support::Episode, project: &Value) -> Vec<Value> {
    let raw = raw["shots"]
        .as_array()
        .or_else(|| raw["storyboards"].as_array())
        .filter(|items| (2..=4).contains(&items.len()));
    let count = raw.map(Vec::len).unwrap_or(3);
    let segments = segments(
        &section.body,
        count,
        project["shot_script_max_chars"]
            .as_i64()
            .unwrap_or(400)
            .max(1) as usize,
    );
    (0..count).map(|index| { let item = raw.and_then(|items|items.get(index)).unwrap_or(&Value::Null); let prompt = item["prompt"].as_str().filter(|value|rich_prompt(value)).map(str::to_owned).unwrap_or_else(||fallback_prompt(section,&segments[index],index+1,project)); json!({"id":item["id"].as_str().unwrap_or(&format!("shot_{}_{}",section.number,index+1)),"title":item["title"].as_str().unwrap_or(&format!("第{}集镜头{}",section.number,index+1)),"original_text":segments[index],"prompt":prompt,"references":valid_references(&item["references"]),"duration_seconds":item["duration"].as_i64().or_else(||item["duration_seconds"].as_i64()).unwrap_or(10).clamp(3,15)}) }).collect()
}

fn segments(value: &str, count: usize, limit: usize) -> Vec<String> {
    let chars = value.chars().collect::<Vec<_>>();
    (0..count)
        .map(|index| {
            let start = chars.len() * index / count;
            let end = chars.len() * (index + 1) / count;
            chars[start..end]
                .iter()
                .collect::<String>()
                .chars()
                .take(limit)
                .collect()
        })
        .collect()
}
fn rich_prompt(value: &str) -> bool {
    [
        "场景：",
        "角色：",
        "风格：",
        "光线：",
        "位置：",
        "【镜头",
        "@图",
    ]
    .iter()
    .all(|part| value.contains(part))
}
fn fallback_prompt(
    _section: &support::Episode,
    segment: &str,
    index: usize,
    project: &Value,
) -> String {
    format!("场景：\n@图1（待匹配场景）\n\n角色：\n@图2（待匹配角色）\n\n道具：\n@图3（待匹配道具）\n\n风格：{}，叙述背景主题为{}，细节丰富。\n光线：根据当前剧情情绪设置自然且连续的主光。\n位置：@图2 位于画面主体区域，与 @图1 的空间关系清晰。\n\n【镜头{index} | 时长5s | 时间：按剧情】中景，平视，镜头稳定推进。@图2 {segment}\n【镜头{} | 时长5s | 时间：按剧情】近景，轻微推近，承接前一动作并留下下一镜线索。",project["style"].as_str().unwrap_or("真人风格"),project["theme"].as_str().unwrap_or("都市"),index+1)
}
fn episode_number(item: &Value) -> Option<i64> {
    let value = item["name"].as_str().or_else(|| item["title"].as_str())?;
    let part = value.strip_prefix('第')?.trim_start();
    let number = part
        .chars()
        .take_while(char::is_ascii_digit)
        .collect::<String>()
        .parse()
        .ok()?;
    part.contains('集').then_some(number)
}
fn valid_asset(item: &Value) -> Option<Value> {
    let kind = match item["type"].as_str()?.trim() {
        "character" | "角色" => "character",
        "scene" | "场景" => "scene",
        "prop" | "道具" => "prop",
        _ => return None,
    };
    let name = item["name"].as_str()?.trim();
    let prompt = item["prompt"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| format!("剧本中出现的{kind}“{name}”，请保持其可复用的视觉连续性。"));
    (!name.is_empty()).then(|| json!({"id":item["id"],"type":kind,"name":name,"prompt":prompt,"voice_id":item["voice_id"],"variants":if kind == "character" { valid_variants(&item["variants"]) } else { Vec::new() },"status":NOT_GENERATED}))
}

fn valid_variants(items: &Value) -> Vec<Value> {
    let mut names = HashSet::new();
    items.as_array().into_iter().flatten().filter_map(|item| {
        let name = item["name"].as_str()?.trim();
        let prompt = item["prompt"].as_str()?.trim();
        (!name.is_empty() && !prompt.is_empty() && names.insert(name.to_owned())).then(|| json!({"id":item["id"],"name":name,"prompt":prompt,"episode_numbers":item["episode_numbers"]}))
    }).collect()
}

fn valid_references(items: &Value) -> Vec<Value> {
    items.as_array().into_iter().flatten().filter_map(|item| {
        let kind = item["asset_type"].as_str().or_else(|| item["type"].as_str())?.trim();
        let name = item["asset_name"].as_str().or_else(|| item["name"].as_str())?.trim();
        (["character", "scene", "prop"].contains(&kind) && !name.is_empty()).then(|| json!({"asset_type":kind,"asset_name":name,"variant_name":item["variant_name"].as_str().or_else(|| item["form_name"].as_str())}))
    }).collect()
}

fn unique_assets(items: Vec<Value>) -> Vec<Value> {
    let mut unique = Vec::<Value>::new();
    for item in items {
        let existing = unique
            .iter_mut()
            .find(|current| current["type"] == item["type"] && current["name"] == item["name"]);
        let Some(existing) = existing else {
            unique.push(item);
            continue;
        };
        for variant in item["variants"].as_array().into_iter().flatten() {
            let Some(variants) = existing["variants"].as_array_mut() else {
                continue;
            };
            if !variants
                .iter()
                .any(|current| current["name"] == variant["name"])
            {
                variants.push(variant.clone());
            }
        }
    }
    unique
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::{batch_progress, valid_asset};

    #[test]
    fn long_drama_batches_use_distinct_visible_progress() {
        assert_eq!(batch_progress(0, 3), 65);
        assert_eq!(batch_progress(1, 3), 68);
        assert_eq!(batch_progress(2, 3), 72);
        assert_eq!(batch_progress(1, 2), 70);
    }

    #[test]
    fn asset_names_survive_missing_model_prompts_and_chinese_types() {
        let asset = valid_asset(&json!({"type":"角色","name":"赵峰"})).expect("named model asset");
        assert_eq!(asset["type"], "character");
        assert_eq!(asset["name"], "赵峰");
        assert!(asset["prompt"]
            .as_str()
            .is_some_and(|text| !text.is_empty()));
    }
}
